using System.Globalization;
using System.IO;
using System.Windows;
using Microsoft.Win32;
namespace PhotoTrail.Windows;
public partial class MainWindow {
 PhotoGpxPlan? photoGpxPlan;PhotoRow[] photoGpxSelection=[];int photoGpxRevision;string? generatedGpx;string? generatedGpxHash;ImportSource? generatedGpxVersion;bool photoGpxJoining;
 private void PhotoGpxInputChanged(object sender,RoutedEventArgs e){if(!IsLoaded)return;photoGpxRevision++;photoGpxPlan=null;if(GpxExportButton is not null)GpxExportButton.IsEnabled=false;}
 private async void PreviewPhotoGpx(object sender,RoutedEventArgs e){if(busy||photoGpxJoining)return;WorkspaceTabs.SelectedIndex=1;PhotoGpxPanel.IsExpanded=true;photoGpxPlan=null;GpxExportButton.IsEnabled=false;var selected=Selected;int revision=++photoGpxRevision;try{if(InspectorHasInput())throw new InvalidOperationException("请先处理未应用字段输入。");if(!decimal.TryParse(GpxSegmentGap.Text,NumberStyles.AllowLeadingSign|NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out var gap))throw new ArgumentException("请输入有限断段秒数。");BeginOperation();PhotoGpxControls.IsEnabled=false;var plan=await PhotoGpxPlan.CreateAsync(selected.Select(r=>r.Document).ToArray(),gap,operation!.Token);if(revision!=photoGpxRevision||!Selected.SequenceEqual(selected))throw new IOException("照片选择或参数已变化。");photoGpxSelection=selected;photoGpxPlan=plan;PhotoGpxRows.ItemsSource=plan.Rows;var times=plan.Data.Segments.SelectMany(s=>s).Select(p=>p.Time!.Value).ToArray();PhotoGpxStatus.Text=$"冻结{plan.Rows.Length}张，{plan.Count}有效点/{plan.Data.Segments.Count}段，跳过{plan.Rows.Length-plan.Count}；相邻间隔严格大于{gap}秒断段。"+(times.Length>0?$" {times.Min():O} → {times.Max():O}":"无有效点，不能导出空成功文件。")+" 生成不保存照片草稿。";}catch(Exception error){PhotoGpxStatus.Text="照片GPX未生成："+(error is OperationCanceledException?"已取消。":error.Message);}finally{PhotoGpxControls.IsEnabled=true;if(busy)EndOperation();GpxExportButton.IsEnabled=photoGpxPlan?.Count>0;}}
 private void ChoosePhotoGpx(object s,RoutedEventArgs e){if(busy)return;var dialog=new SaveFileDialog{Filter="GPX1.1|*.gpx",DefaultExt=".gpx",OverwritePrompt=false,FileName="phototrail-photos.gpx"};if(dialog.ShowDialog(this)==true)PhotoGpxOutput.Text=dialog.FileName;}
 private async void ExportPhotoGpx(object s,RoutedEventArgs e){if(busy||photoGpxJoining||photoGpxPlan is not {} plan)return;if(PhotoGpxOutput.Text.Length==0){ChoosePhotoGpx(s,e);if(PhotoGpxOutput.Text.Length==0)return;}var selection=photoGpxSelection;var target=PhotoGpxOutput.Text;var name=PhotoGpxName.Text;try{if(!Selected.SequenceEqual(selection))throw new IOException("照片选择已改变，请重新生成预览。");BeginOperation();PhotoGpxControls.IsEnabled=false;await plan.ExportAsync(selection.Select(r=>r.Document).ToArray(),target,name,operation!.Token);generatedGpx=Path.GetFullPath(target);generatedGpxHash=await PhotoDocument.HashAsync(generatedGpx);generatedGpxVersion=ImportSource.Read(generatedGpx);PhotoGpxStatus.Text=$"GPX另存并由生产读取器回读一致：{plan.Count}点/{plan.Data.Segments.Count}段。照片及其草稿未保存；加入工作区须明确点击。";}catch(Exception error){PhotoGpxStatus.Text="GPX未交付："+(error is OperationCanceledException?"已取消。":error.Message);}finally{PhotoGpxControls.IsEnabled=true;if(busy)EndOperation();GpxAddButton.IsEnabled=generatedGpx is not null;}}
 private async void AddPhotoGpxToWorkspace(object s,RoutedEventArgs e){if(busy||photoGpxJoining||generatedGpx is null||generatedGpxVersion is null)return;var path=generatedGpx;var expected=generatedGpxHash;var version=generatedGpxVersion;photoGpxJoining=true;bool validating=true;BeginOperation();var request=operation!;PhotoGpxControls.IsEnabled=false;try{using var guard=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);version.RequireCurrent();if(await PhotoDocument.HashAsync(path,request.Token)!=expected||generatedGpx!=path||!ReferenceEquals(generatedGpxVersion,version))throw new IOException("已导出GPX或当前生成记录改变，不能按旧结果加入。");request.Token.ThrowIfCancellationRequested();EndOperation();validating=false;await ImportTracksAsync([path]);}catch(Exception error){PhotoGpxStatus.Text="生成轨迹未加入："+(error is OperationCanceledException?"已取消。":error.Message);}finally{if(validating&&ReferenceEquals(operation,request))EndOperation();photoGpxJoining=false;PhotoGpxControls.IsEnabled=true;}}
}
